import addonHandler
import config
from logHandler import log

from .beeps import deserializePattern, serializePattern

addonHandler.initTranslation()

addonInstance = addonHandler.getCodeAddon()
addonName = addonInstance.name
addonSummary = addonInstance.manifest["summary"]


class Mode(StrEnum):
    OFF = "off"
    SPEAK = "speak"
    BEEPS = "beeps"
    WAVE = "wave"

    @property
    def displayString(self):
        return MODE_LABELS[self]

    @classmethod
    def fromConfig(cls, value):
        try:
            return cls(value)
        except ValueError:
            log.warning(f"Unknown notification action {value!r}, falling back to {cls.SPEAK.value}")
            return cls.SPEAK


MODES = tuple(Mode)

MODE_LABELS = {
    # Translators: An action for a notification, meaning that it is not reported at all.
    Mode.OFF: _("Off"),
    # Translators: An action for a notification, meaning that it is spoken.
    Mode.SPEAK: _("Speak"),
    # Translators: An action for a notification, meaning that it is replaced by beeps.
    Mode.BEEPS: _("Beeps"),
    # Translators: An action for a notification, meaning that it is replaced by a wave file.
    Mode.WAVE: _("Wave file"),
}


class Kind(StrEnum):
    ACTION = "action"
    TOGGLE = "toggle"


class Settings(NamedTuple):
    configKey: str
    label: str
    defaultMode: Mode = Mode.SPEAK
    activityIDs: tuple[str, ...] = ()
    kind: Kind = Kind.ACTION

    @property
    def notificationIDs(self):
        return self.activityIDs or (self.configKey,)

    @property
    def configSpec(self):
        return {field.name: field.specFor(self) for field in FIELDS}


