def unchanged(value):
    return value


def _modeSpec(setting):
    modes = ", ".join(repr(mode.value) for mode in MODES)
    return f"option({modes}, default={setting.defaultMode.value!r})"


class Field(NamedTuple):
    name: str
    spec: str | Callable
    default: Callable
    load: Callable = unchanged
    dump: Callable = unchanged

    def specFor(self, setting):
        return self.spec(setting) if callable(self.spec) else self.spec


FIELDS = (
    Field("mode", _modeSpec, lambda: Mode.SPEAK, Mode.fromConfig, lambda mode: mode.value),
    Field("useCustomMessage", "boolean(default=false)", bool),
    Field("customMessage", 'string(default="")', str),
    Field("beepPattern", "string_list(default=list())", list, deserializePattern, serializePattern),
    Field("waveFile", 'string(default="")', str),
    Field("waveVolume", "integer(0, 100, default=100)", lambda: 100),
)


class EventConfig:
    def __init__(self, **values):
        for field in FIELDS:
            setattr(self, field.name, values.get(field.name, field.default()))

    @classmethod
    def fromConfig(cls, section):
        if isinstance(section, (str, bool)):
            return cls(mode=Mode.OFF if _isFalse(section) else Mode.SPEAK)
        return cls(**{field.name: field.load(section[field.name]) for field in FIELDS})

    def save(self, section):
        for field in FIELDS:
            section[field.name] = field.dump(getattr(self, field.name))


class EventConfigs(dict):
    def __getattr__(self, name):
        try:
            return self[name]
        except KeyError:
            raise AttributeError(name) from None


def loadEventConfigs():
    migrateConfig()
    edgeConf = config.conf[addonName]
    return EventConfigs(
        (setting.configKey, EventConfig.fromConfig(edgeConf[setting.configKey])) for setting in settingItems
    )


def loadNotificationConfigs():
    configs = loadEventConfigs()
    return EventConfigs(
        (activityID, configs[setting.configKey])
        for setting in settingItems
        for activityID in setting.notificationIDs
    )


def saveEventConfigs(configs):
    edgeConf = config.conf[addonName]
    for setting in settingItems:
        configs[setting.configKey].save(edgeConf[setting.configKey])


def migrateConfig():
    knownKeys = {setting.configKey for setting in settingItems}
    for profile in config.conf.profiles:
        section = profile.get(addonName)
        if section is None:
            continue
        for key, value in list(section.items()):
            if isinstance(value, dict):
                continue
            try:
                del section[key]
                if key in knownKeys:
                    mode = Mode.OFF if _isFalse(value) else Mode.SPEAK
                    section[key] = {"mode": mode.value}
            except Exception:
                log.error(f"Could not migrate the configuration of {key}", exc_info=True)


def _isFalse(value):
    if isinstance(value, str):
        return value.strip().lower() in ("false", "no", "off", "0")
    return not value


config.conf.spec[addonName] = {setting.configKey: setting.configSpec for setting in settingItems}
